// The Gradle build for the inventory service, generated by Spring Initializr and then annotated.
//
// Kotlin: this file is Kotlin, not Groovy. `build.gradle.kts` is compiled like any other Kotlin
// source, so the IDE can autocomplete and type-check it. Almost every block below
// (`plugins { }`, `java { }`, `dependencies { }`) is a function call whose last argument is a
// lambda. Kotlin lets a trailing lambda sit outside the parentheses, and when a function takes
// nothing else the parentheses disappear entirely. That's why `plugins { ... }` reads like
// configuration even though it's really `plugins({ ... })`.

plugins {
    // Kotlin: `kotlin("jvm")` is a helper that expands to `id("org.jetbrains.kotlin.jvm")`.
    // This plugin runs the Kotlin compiler and targets the JVM.
    kotlin("jvm") version "2.3.21"

    // Spring: Kotlin classes and functions are `final` unless marked `open` (Java is the
    // opposite). Spring needs to subclass some beans at runtime to add behavior such as
    // transactions and `@Configuration` proxies, and it can't subclass a final class. This
    // compiler plugin ("all-open") automatically makes classes annotated with Spring
    // annotations (`@Component`, `@Service`, `@Configuration`, `@Transactional`, ...) open,
    // so we don't have to write `open` everywhere.
    kotlin("plugin.spring") version "2.3.21"

    // Spring: adds `bootRun` (run the app from the source tree) and `bootJar` (build one
    // runnable "fat" jar that contains every dependency).
    id("org.springframework.boot") version "4.1.1"

    // Spring: imports Spring Boot's "bill of materials", a curated list of library versions
    // tested together. That's why most dependencies below have no version number.
    id("io.spring.dependency-management") version "1.1.7"
}

group = "com.robertwoolbright"
version = "0.0.1-SNAPSHOT"

java {
    // Why: a toolchain makes Gradle compile and test with JDK 21 no matter which JDK happens
    // to be running Gradle itself (Gradle downloads or finds one). Reviewers who clone the repo
    // get the same Java version we used. The Kotlin plugin reads this too, so the bytecode
    // targets Java 21.
    toolchain {
        // Kotlin: `=` on a Gradle property calls its setter (Gradle's "lazy property
        // assignment"). The older Kotlin DSL spelling was `languageVersion.set(...)`.
        languageVersion = JavaLanguageVersion.of(21)
    }
}

repositories {
    // Where Gradle downloads dependencies from.
    mavenCentral()
}

dependencies {
    // Configurations decide where each library is visible:
    //   implementation     compile + runtime classpath of the app
    //   runtimeOnly        runtime only; our code never refers to it directly
    //   developmentOnly    `bootRun` only; excluded from tests and from the bootJar
    //   testImplementation / testRuntimeOnly   the same idea, for src/test

    // Spring: runs our versioned SQL migrations (src/main/resources/db/migration) against the
    // database at startup, before the app serves requests. Spring Boot 4 split its starters
    // into smaller modules, so Flyway support now has its own starter.
    implementation("org.springframework.boot:spring-boot-starter-flyway")
    // Why: since Flyway 10, support for each database lives in its own module. Without this,
    // Flyway refuses to run against Postgres.
    implementation("org.flywaydb:flyway-database-postgresql")

    // Spring: a pooled `DataSource` (HikariCP), `JdbcClient`/`JdbcTemplate`, and a transaction
    // manager, all auto-configured. `JdbcClient` is the data-access API we chose.
    implementation("org.springframework.boot:spring-boot-starter-jdbc")

    // Spring: Spring MVC on an embedded Tomcat server, plus Jackson for JSON. (Spring Boot 4
    // renamed `spring-boot-starter-web` to `spring-boot-starter-webmvc`.)
    implementation("org.springframework.boot:spring-boot-starter-webmvc")

    // Spring: Spring reads Kotlin-specific metadata through kotlin-reflect, such as which
    // constructor parameters are nullable and which have default values.
    implementation("org.jetbrains.kotlin:kotlin-reflect")

    // Kotlin: teaches Jackson to build Kotlin classes. A `data class` has no no-arg constructor
    // and no setters; this module lets Jackson call the primary constructor, and it respects
    // non-null types and default argument values. (`tools.jackson` is Jackson 3's group ID,
    // the version used by Spring Boot 4.)
    implementation("tools.jackson.module:jackson-module-kotlin")

    // Spring: on `bootRun`, runs `docker compose up` on compose.yaml and points the DataSource
    // at the Postgres container, so there is no database URL or password to configure.
    // `developmentOnly` keeps it out of tests (they use Testcontainers) and out of the jar.
    developmentOnly("org.springframework.boot:spring-boot-docker-compose")

    // The Postgres JDBC driver. We only code against the standard JDBC interfaces, so the
    // driver is only needed at runtime.
    runtimeOnly("org.postgresql:postgresql")

    // Spring: the test halves of the starters above. Each brings its test "slices" (e.g.
    // `@WebMvcTest` with MockMvc, `@JdbcTest`) and, transitively, spring-boot-starter-test
    // (JUnit 5, AssertJ, Mockito).
    testImplementation("org.springframework.boot:spring-boot-starter-flyway-test")
    testImplementation("org.springframework.boot:spring-boot-starter-jdbc-test")
    testImplementation("org.springframework.boot:spring-boot-starter-webmvc-test")

    // Spring: provides `@ServiceConnection`, which lets a Testcontainers container supply the
    // DataSource connection details (see support/TestcontainersConfiguration.kt).
    testImplementation("org.springframework.boot:spring-boot-testcontainers")

    // Kotlin: `kotlin.test` assertions (`assertEquals`, `assertFailsWith`, ...) running on JUnit 5.
    testImplementation("org.jetbrains.kotlin:kotlin-test-junit5")

    // Why: tests run against a real Postgres in Docker, not an in-memory H2 lookalike, because
    // the oversell protection relies on Postgres behavior (row locks, CHECK constraints,
    // `ON CONFLICT`). See the README decision record.
    testImplementation("org.testcontainers:testcontainers-junit-jupiter")
    testImplementation("org.testcontainers:testcontainers-postgresql")

    // Gradle 9 no longer bundles the JUnit Platform launcher; it must be on the test runtime
    // classpath for Gradle to start JUnit 5.
    testRuntimeOnly("org.junit.platform:junit-platform-launcher")
}

kotlin {
    compilerOptions {
        freeCompilerArgs.addAll(
            // Kotlin: Java libraries mark nullability with annotations. Types without them
            // become "platform types" (shown as `String!`), which Kotlin can't null-check.
            // `strict` turns JSR-305 annotations (`@Nonnull`/`@Nullable`) into real Kotlin
            // `String` / `String?` types, so a null from Java is a compile error, not a
            // runtime crash. (Spring Framework 7 uses the newer JSpecify annotations, which
            // Kotlin 2 already enforces; this covers libraries still on JSR-305.)
            "-Xjsr305=strict",
            // Kotlin: one `val` in a primary constructor is a parameter, a property and a
            // backing field all at once, so an annotation on it is ambiguous. This option
            // puts the annotation on the parameter and on the property as well (or on the
            // field if there's no property), which is where frameworks like Jackson and
            // Bean Validation look. This will be Kotlin's default in a future release.
            "-Xannotation-default-target=param-property",
        )
    }
}

// Kotlin: `withType<Test>` uses a reified type parameter: the type is written in angle brackets
// instead of passed as `Test::class.java`, which is what Java (and Groovy) would need.
tasks.withType<Test> {
    // Run tests on the JUnit 5 platform (Gradle's default is still JUnit 4).
    useJUnitPlatform()
}
